// Minimal endless‑runner based on IDEA.md
// Canvas with id="game"

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  // full‑window size
  const resize = () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  };
  window.addEventListener('resize', resize);
  resize();

  // Player settings
  const player = { w: 30, h: 30, x: 80, y: 0, vy: 0, onGround: false };
  const GRAVITY = 0.6;
  const JUMP = -12;
  const SLIDE_TIME = 15; // frames
  let slideCounter = 0;

  // Obstacles
  const obstacles = [];
  const OBSTACLE_SPACING = 200;
  const OBSTACLE_SPEED = 6;
  let frame = 0;

  const createObstacle = () => {
    // Randomly choose type: 0 = low (jump over), 1 = high (slide under)
    const type = Math.random() < 0.5 ? 0 : 1;
    const w = 30;
    const h = type === 0 ? 30 : canvas.height * 0.4;
    const y = type === 0 ? canvas.height - h - 10 : 10; // high obstacle from top
    obstacles.push({ w, h, x: canvas.width + w, y, type });
  };

  const handleInput = (e) => {
    if (e.type === 'keydown') {
      if (e.code === 'Space' || e.key === ' ' || e.key === 'ArrowUp') {
        if (player.onGround) {
          player.vy = JUMP;
          player.onGround = false;
        }
      } else if (e.key === 'ArrowDown') {
        if (player.onGround && slideCounter === 0) {
          slideCounter = SLIDE_TIME;
        }
      }
    }
  };
  window.addEventListener('keydown', handleInput);

  const update = () => {
    // player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    const groundY = canvas.height - player.h - 10;
    if (player.y >= groundY) {
      player.y = groundY;
      player.vy = 0;
      player.onGround = true;
    }
    if (slideCounter > 0) {
      slideCounter--;
      player.h = 15; // crouch height
    } else {
      player.h = 30;
    }

    // obstacles movement
    obstacles.forEach(o => (o.x -= OBSTACLE_SPEED));
    // remove off‑screen
    while (obstacles.length && obstacles[0].x + obstacles[0].w < 0) obstacles.shift();
    // spawn new
    if (frame % OBSTACLE_SPACING === 0) createObstacle();
    frame++;

    // collision detection
    for (const o of obstacles) {
      if (
        player.x < o.x + o.w &&
        player.x + player.w > o.x &&
        player.y < o.y + o.h &&
        player.y + player.h > o.y
      ) {
        // lose condition – simple reload
        alert('Game Over');
        document.location.reload();
        break;
      }
    }
  };

  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // ground line
    ctx.fillStyle = '#222';
    ctx.fillRect(0, canvas.height - 10, canvas.width, 10);
    // player
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // obstacles
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
  };

  const loop = () => {
    update();
    draw();
    requestAnimationFrame(loop);
  };
  loop();
})();
